import{_ as t}from"./chunks/difficulty_easy.76S4H_Nf.js";import{_ as a}from"./chunks/remote_control.ss1psCxn.js";import{_ as r}from"./chunks/altitude_icon.CQEDErje.js";import{_ as i}from"./chunks/altitude_fw.DTK0l5oK.js";import{_ as d,o,c as l,al as _}from"./chunks/framework.7vp1BMOE.js";const P=JSON.parse('{"title":"Режим Altitude (Фіксоване крило)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_modes_fw/altitude.md","filePath":"uk/flight_modes_fw/altitude.md"}'),n={name:"uk/flight_modes_fw/altitude.md"};function s(m,e,c,h,f,p){return o(),l("div",null,[...e[0]||(e[0]=[_('<h1 id="режим-altitude-фіксоване-крило" tabindex="-1">Режим Altitude (Фіксоване крило) <a class="header-anchor" href="#режим-altitude-фіксоване-крило" aria-label="Permalink to &quot;Режим Altitude (Фіксоване крило)&quot;">​</a></h1><p><img src="'+t+'" title="Easy to fly" width="30px"> <img src="'+a+'" title="Manual/Remote control required" width="30px"> <img src="'+r+'" title="Altitude required (e.g. Baro, Rangefinder)" width="30px"></p><p>The <em>Altitude</em> flight mode is the safest and easiest non-GPS manual mode. Це полегшує пілотам контроль висоти транспортного засобу, і зокрема досягати і підтримувати фіксовану висоту. Режим не буде намагатися утримати курс транспортного засобу від вітру. Швидкість активно контролюється, якщо встановлений датчик швидкості.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><em>Altitude mode</em> is similar to <a href="./../flight_modes_fw/cruise">Cruise mode</a> in that both modes level the vehicle and maintain altitude when sticks are released. The difference is that Cruise mode holds the actual flight path (course) steady against wind, while altitude just holds the heading.</p></div><p>The vehicle performs a <a href="https://en.wikipedia.org/wiki/Coordinated_flight" target="_blank" rel="noreferrer">coordinated turn</a> if the roll sticks are non-zero, while the pitch stick controls the rate of ascent/descent. Засувка визначає швидкість повітря — при 50% засувки літак буде утримувати свою поточну висоту з заданою крейсерською швидкістю.</p><p>Коли всі стіки відпущені/центровані (без кочення, тангажу, повороту та близько 50% керування газом), літак повернеться до прямого, рівного польоту (залежно від вітру) та збереже свою поточну висоту. This makes it easy to recover from any problems when flying. Крен, тангаж та риск - всі кутово-керовані (тому неможливо перекочувати або робити петлю транспортному засобу).</p><p>Стік повороту може бути використана для збільшення/зменшення кута приводу автомобіля на поворотах. Якщо контролер фіксований у центрі, то він самостійно здійснює координацію повороту, що означає, що він застосовує необхідну швидкість розвороту для поточного кута крену, щоб виконати плавний поворот.</p><p>The diagram below shows the mode behaviour visually (for a <a href="./../getting_started/rc_transmitter_receiver#transmitter_modes">mode 2 transmitter</a>).</p><p><img src="'+i+'" alt="Altitude Control FW"></p><h2 id="технічнии-підсумок" tabindex="-1">Технічний підсумок <a class="header-anchor" href="#технічнии-підсумок" aria-label="Permalink to &quot;Технічний підсумок&quot;">​</a></h2><p>Altitude mode like <a href="./../flight_modes_fw/stabilized">Stabilized mode</a> but with altitude stabilization. Швидкість також стабілізується, якщо встановлений датчик швидкості. Курс транспортного засобу не фіксується, і він може дрейфувати по причині вітру.</p><ul><li>Центровані вхідні показники крену/тангажу/рискання (в межах дедбенду): <ul><li>Автопілот рівномірно підтримує транспортний засіб і утримує висоту і швидкість повітря.</li></ul></li><li>Зовнішній центр: <ul><li>Стік регулює висота польоту.</li><li>Резервний стік керує швидкістю літального апарату, якщо підключений датчик швидкості. Without an airspeed sensor the vehicle will fly level at trim throttle (<a href="./../advanced_config/parameter_reference#FW_THR_TRIM">FW_THR_TRIM</a>), increasing or decreasing throttle as needed to climb or descend.</li><li>Стік керування використовує кут крена. Autopilot will maintain <a href="https://en.wikipedia.org/wiki/Coordinated_flight" target="_blank" rel="noreferrer">coordinated flight</a>.</li><li>Стік крену додає додатковий значення швидкості рискання (додається до розрахованого автопілотом для підтримки координованого польоту). Може бути використаний для ручної зміни кута рискання безпілотного засобу.</li></ul></li><li>Потрібен ручний ввід управління (наприклад, за допомогою пульта дистанційного керування, джойстика).</li><li>Необхідне джерело вимірювання висоти (зазвичай барометр або GPS)</li></ul><h3 id="mode-requirements" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_alt"><code>mode_req_local_alt</code></a> — Local altitude relative to EKF2 origin (&#39;0&#39;) position</li><li><a href="./../flight_modes/mode_requirements#mode_req_manual_control"><code>mode_req_manual_control</code></a> — Requires stick input</li></ul><h2 id="параметри" tabindex="-1">Параметри <a class="header-anchor" href="#параметри" aria-label="Permalink to &quot;Параметри&quot;">​</a></h2><p>Режим впливає на наступні параметри:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Опис</th></tr></thead><tbody><tr><td><a id="FW_AIRSPD_MIN"></a><a href="./../advanced_config/parameter_reference#FW_AIRSPD_MIN">FW_AIRSPD_MIN</a></td><td>Мінімальна швидкість. За замовчуванням: 10 м/с.</td></tr><tr><td><a id="FW_AIRSPD_MAX"></a><a href="./../advanced_config/parameter_reference#FW_AIRSPD_MAX">FW_AIRSPD_MAX</a></td><td>Максимальна швидкість. За замовчуванням: 20 м/с.</td></tr><tr><td><a id="FW_AIRSPD_TRIM"></a><a href="./../advanced_config/parameter_reference#FW_AIRSPD_TRIM">FW_AIRSPD_TRIM</a></td><td>Крейсерська швидкість. За замовчуванням: 15 м/с.</td></tr><tr><td><a id="FW_MAN_P_MAX"></a><a href="./../advanced_config/parameter_reference#FW_MAN_P_MAX">FW_MAN_P_MAX</a></td><td>Установлення максимального кроку в режимі стабілізації кута нахилу. За замовчуванням: 45 градусів.</td></tr><tr><td><a id="FW_MAN_R_MAX"></a><a href="./../advanced_config/parameter_reference#FW_MAN_R_MAX">FW_MAN_R_MAX</a></td><td>Максимальне значення крена в режимі стабілізації кута нахилу. За замовчуванням: 45 градусів.</td></tr><tr><td><a id="FW_T_CLMB_R_SP"></a><a href="./../advanced_config/parameter_reference#FW_T_CLMB_R_SP">FW_T_CLMB_R_SP</a></td><td>Максимальна задана швидкість підйому. За замовчуванням: 3 м/с.</td></tr><tr><td><a id="FW_T_SINK_R_SP"></a><a href="./../advanced_config/parameter_reference#FW_T_SINK_R_SP">FW_T_SINK_R_SP</a></td><td>Максимальне значення зниження швидкості. За замовчуванням: 2 м/с.</td></tr></tbody></table><h2 id="mavlink-commands" tabindex="-1">MAVLink Commands <a class="header-anchor" href="#mavlink-commands" aria-label="Permalink to &quot;MAVLink Commands&quot;">​</a></h2><p>The following commands are relevant to this mode:</p><ul><li><p><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_CHANGE_SPEED" target="_blank" rel="noreferrer">MAV_CMD_DO_CHANGE_SPEED</a> — Sets the cruise airspeed for centred throttle stick.</p><p>This requires an airspeed sensor. Only the airspeed speed type is handled (<code>param1</code> must be <code>0</code>); other speed types are ignored. At centered throttle the vehicle holds the commanded airspeed (<code>param2</code>) if a positive value is set (non-positive values are ignored). The value is constrained between <a href="./../advanced_config/parameter_reference#FW_AIRSPD_MIN">FW_AIRSPD_MIN</a> and <a href="./../advanced_config/parameter_reference#FW_AIRSPD_MAX">FW_AIRSPD_MAX</a>, and defaults to <a href="./../advanced_config/parameter_reference#FW_AIRSPD_TRIM">FW_AIRSPD_TRIM</a> if no airspeed has been commanded. Deflecting the throttle stick scales the airspeed toward <code>FW_AIRSPD_MIN</code> (back) or <code>FW_AIRSPD_MAX</code> (forward) around this value. The commanded airspeed resets to <code>FW_AIRSPD_TRIM</code> on every flight mode change.</p></li></ul><p>Note, other commands may be supported.</p>',22)])])}const v=d(n,[["render",s]]);export{P as __pageData,v as default};
